-- ============================================================
-- ERP Colegio Internacional Little Horizons
-- database.sql: instalacion completa en una base nueva
-- Requiere MySQL 8.0.16 o superior, InnoDB y utf8mb4.
-- Autor del proyecto: Juan Esteban Cardenas Rivera.
-- Datos ficticios; referencia academica fija: 2026-11-16.
--
-- SECCION 1: DDL completo, basado en el esquema corregido.
-- SECCION 2: DML de prueba, en orden de llaves foraneas.
-- No elimina bases ni tablas. Ejecutar una sola vez sobre una
-- base vacia; no es una migracion ni un script de reinicio.
-- No desactiva llaves foraneas ni ignora errores de insercion.
-- Facturas y detalle_factura se conservan por compatibilidad con
-- el esquema suministrado, pero permanecen vacias: la facturacion
-- y los PDF estan excluidos del alcance de la aplicacion.
-- ============================================================

CREATE DATABASE IF NOT EXISTS `erp_little_horizons`
    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `erp_little_horizons`;
SET NAMES utf8mb4;

-- ============================================================
-- SECCION 1 - DDL: ESTRUCTURA
-- ============================================================

-- Tabla: grados
CREATE TABLE `grados` (
  `id_grado` int NOT NULL AUTO_INCREMENT,
  `nombre_grado` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ej: Preescolar, Primero, ... Once',
  `nivel_numerico` int NOT NULL COMMENT '0 para preescolar, 1-11 para grados',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_grado`),
  UNIQUE KEY `nombre_grado` (`nombre_grado`),
  UNIQUE KEY `nivel_numerico` (`nivel_numerico`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Catálogo de grados académicos del colegio';

-- Tabla: estudiantes
CREATE TABLE `estudiantes` (
  `id_estudiante` int NOT NULL AUTO_INCREMENT,
  `tipo_documento` enum('RC','TI','CC','CE','PPT','Pasaporte') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TI',
  `numero_documento` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `primer_nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `segundo_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primer_apellido` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `segundo_apellido` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_nacimiento` date NOT NULL,
  `genero` enum('M','F','Otro') COLLATE utf8mb4_unicode_ci NOT NULL,
  `direccion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefono` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `correo_electronico` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_sangre` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alergias` text COLLATE utf8mb4_unicode_ci,
  `condiciones_medicas` text COLLATE utf8mb4_unicode_ci,
  `fecha_ingreso` date NOT NULL,
  `estado` enum('Activo','Graduado','Retirado','Suspendido') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activo',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_estudiante`),
  UNIQUE KEY `uq_estudiante_documento` (`tipo_documento`,`numero_documento`),
  KEY `idx_estudiante_estado` (`estado`),
  KEY `idx_estudiante_nombre` (`primer_apellido`,`segundo_apellido`,`primer_nombre`),
  CONSTRAINT `estudiantes_chk_1` CHECK ((`fecha_ingreso` >= `fecha_nacimiento`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Información completa de estudiantes';

-- Tabla: acudientes
CREATE TABLE `acudientes` (
  `id_acudiente` int NOT NULL AUTO_INCREMENT,
  `tipo_documento` enum('CC','CE','PPT','Pasaporte') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CC',
  `numero_documento` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `primer_nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `segundo_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primer_apellido` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `segundo_apellido` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefono_principal` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `telefono_secundario` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `correo_electronico` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direccion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ocupacion` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_acudiente`),
  UNIQUE KEY `uq_acudiente_documento` (`tipo_documento`,`numero_documento`),
  KEY `idx_acudiente_nombre` (`primer_apellido`,`segundo_apellido`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Acudientes y tutores legales (datos de la persona)';

-- Tabla: estudiante_acudiente
CREATE TABLE `estudiante_acudiente` (
  `id_estudiante` int NOT NULL,
  `id_acudiente` int NOT NULL,
  `parentesco` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Padre, Madre, Abuelo, Tío, Tutor Legal, etc.',
  `es_principal` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Acudiente principal para comunicaciones',
  `es_responsable_financiero` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Responsable de los pagos de este estudiante',
  `es_contacto_emergencia` tinyint(1) NOT NULL DEFAULT '1',
  `principal_unico` tinyint GENERATED ALWAYS AS (if(`es_principal`,1,NULL)) VIRTUAL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_estudiante`,`id_acudiente`),
  UNIQUE KEY `uq_un_principal_por_estudiante` (`id_estudiante`,`principal_unico`),
  KEY `idx_acudiente` (`id_acudiente`),
  CONSTRAINT `estudiante_acudiente_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE CASCADE,
  CONSTRAINT `estudiante_acudiente_ibfk_2` FOREIGN KEY (`id_acudiente`) REFERENCES `acudientes` (`id_acudiente`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Relación entre estudiantes y sus acudientes';

-- Tabla: matriculas
CREATE TABLE `matriculas` (
  `id_matricula` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_grado` int NOT NULL,
  `anio_academico` int NOT NULL COMMENT 'Año académico (ej: 2026)',
  `estado_matricula` enum('Activa','Completada','Retirada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activa',
  `fecha_matricula` date NOT NULL,
  `fecha_retiro` date DEFAULT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_matricula`),
  UNIQUE KEY `uq_matricula` (`id_estudiante`,`anio_academico`),
  KEY `id_grado` (`id_grado`),
  KEY `idx_matricula_anio_grado` (`anio_academico`,`id_grado`),
  KEY `idx_matricula_estado` (`estado_matricula`),
  CONSTRAINT `matriculas_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `matriculas_ibfk_2` FOREIGN KEY (`id_grado`) REFERENCES `grados` (`id_grado`),
  CONSTRAINT `matriculas_chk_1` CHECK (((`fecha_retiro` is null) or (`fecha_retiro` >= `fecha_matricula`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Historial de matrículas por año y grado';

-- Tabla: materias
CREATE TABLE `materias` (
  `id_materia` int NOT NULL AUTO_INCREMENT,
  `codigo_materia` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Código único (ej: MAT-5, ESP-3)',
  `nombre_materia` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `id_grado` int NOT NULL COMMENT 'Grado al que pertenece la materia',
  `horas_semanales` int NOT NULL DEFAULT '2',
  `esta_activa` tinyint(1) NOT NULL DEFAULT '1',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_materia`),
  UNIQUE KEY `codigo_materia` (`codigo_materia`),
  UNIQUE KEY `uq_materia_grado` (`nombre_materia`,`id_grado`),
  KEY `idx_materia_grado` (`id_grado`),
  CONSTRAINT `materias_ibfk_1` FOREIGN KEY (`id_grado`) REFERENCES `grados` (`id_grado`),
  CONSTRAINT `materias_chk_1` CHECK ((`horas_semanales` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Catálogo de materias por grado';

-- Tabla: profesores
CREATE TABLE `profesores` (
  `id_profesor` int NOT NULL AUTO_INCREMENT,
  `tipo_documento` enum('CC','CE','PPT','Pasaporte') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CC',
  `numero_documento` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `primer_nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `segundo_nombre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primer_apellido` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `segundo_apellido` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `correo_electronico` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `telefono` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `especializacion` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Área de especialización',
  `fecha_contratacion` date NOT NULL,
  `estado` enum('Activo','Inactivo','Licencia') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activo',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_profesor`),
  UNIQUE KEY `correo_electronico` (`correo_electronico`),
  UNIQUE KEY `uq_profesor_documento` (`tipo_documento`,`numero_documento`),
  KEY `idx_profesor_estado` (`estado`),
  KEY `idx_profesor_nombre` (`primer_apellido`,`segundo_apellido`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Información de profesores';

-- Tabla: asignaciones_profesor
CREATE TABLE `asignaciones_profesor` (
  `id_asignacion` int NOT NULL AUTO_INCREMENT,
  `id_profesor` int NOT NULL,
  `id_materia` int NOT NULL,
  `anio_academico` int NOT NULL,
  `seccion` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A' COMMENT 'Sección o grupo (A, B, C)',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_asignacion`),
  UNIQUE KEY `uq_asignacion` (`id_profesor`,`id_materia`,`anio_academico`,`seccion`),
  KEY `idx_asignacion_materia` (`id_materia`,`anio_academico`),
  CONSTRAINT `asignaciones_profesor_ibfk_1` FOREIGN KEY (`id_profesor`) REFERENCES `profesores` (`id_profesor`) ON DELETE RESTRICT,
  CONSTRAINT `asignaciones_profesor_ibfk_2` FOREIGN KEY (`id_materia`) REFERENCES `materias` (`id_materia`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Asignación de profesores a materias por año académico';

-- Tabla: horarios_asignacion
CREATE TABLE `horarios_asignacion` (
  `id_horario` int NOT NULL AUTO_INCREMENT,
  `id_asignacion` int NOT NULL,
  `dia_semana` enum('Lunes','Martes','Miércoles','Jueves','Viernes','Sábado') COLLATE utf8mb4_unicode_ci NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fin` time NOT NULL,
  PRIMARY KEY (`id_horario`),
  UNIQUE KEY `uq_horario` (`id_asignacion`,`dia_semana`,`hora_inicio`),
  KEY `idx_horario_dia_hora` (`dia_semana`,`hora_inicio`),
  CONSTRAINT `horarios_asignacion_ibfk_1` FOREIGN KEY (`id_asignacion`) REFERENCES `asignaciones_profesor` (`id_asignacion`) ON DELETE CASCADE,
  CONSTRAINT `horarios_asignacion_chk_1` CHECK ((`hora_fin` > `hora_inicio`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Días y horas de clase de cada asignación (detección de cruces)';

-- Tabla: inscripciones_materia
CREATE TABLE `inscripciones_materia` (
  `id_inscripcion` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_materia` int NOT NULL,
  `anio_academico` int NOT NULL,
  `periodo_academico` enum('I','II','III','IV') COLLATE utf8mb4_unicode_ci NOT NULL,
  `seccion` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A',
  `fecha_inscripcion` date NOT NULL,
  `estado` enum('Activa','Retirada','Completada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activa',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_inscripcion`),
  UNIQUE KEY `uq_inscripcion` (`id_estudiante`,`id_materia`,`anio_academico`,`periodo_academico`),
  KEY `idx_inscripcion_materia_periodo` (`id_materia`,`anio_academico`,`periodo_academico`),
  CONSTRAINT `inscripciones_materia_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `inscripciones_materia_ibfk_2` FOREIGN KEY (`id_materia`) REFERENCES `materias` (`id_materia`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Inscripción de estudiantes en materias por período';

-- Tabla: registros_academicos
CREATE TABLE `registros_academicos` (
  `id_registro` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_materia` int NOT NULL,
  `id_profesor` int NOT NULL,
  `anio_academico` int NOT NULL,
  `periodo_academico` enum('I','II','III','IV','Final') COLLATE utf8mb4_unicode_ci NOT NULL,
  `valor_nota` decimal(2,1) NOT NULL COMMENT 'Nota de 0.0 a 5.0 (estándar colombiano)',
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `fecha_registro` date NOT NULL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_registro`),
  UNIQUE KEY `uq_registro` (`id_estudiante`,`id_materia`,`anio_academico`,`periodo_academico`),
  KEY `idx_registro_materia_periodo` (`id_materia`,`anio_academico`,`periodo_academico`),
  KEY `idx_registro_profesor` (`id_profesor`),
  CONSTRAINT `registros_academicos_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `registros_academicos_ibfk_2` FOREIGN KEY (`id_materia`) REFERENCES `materias` (`id_materia`) ON DELETE RESTRICT,
  CONSTRAINT `registros_academicos_ibfk_3` FOREIGN KEY (`id_profesor`) REFERENCES `profesores` (`id_profesor`) ON DELETE RESTRICT,
  CONSTRAINT `registros_academicos_chk_1` CHECK (((`valor_nota` >= 0.0) and (`valor_nota` <= 5.0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Calificaciones de estudiantes';

-- Tabla: asistencias
CREATE TABLE `asistencias` (
  `id_asistencia` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_materia` int NOT NULL,
  `fecha_asistencia` date NOT NULL,
  `estado_asistencia` enum('Presente','Ausente','Tardanza','Excusa Médica') COLLATE utf8mb4_unicode_ci NOT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `registrado_por` int DEFAULT NULL COMMENT 'Profesor que registró la asistencia',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_asistencia`),
  UNIQUE KEY `uq_asistencia` (`id_estudiante`,`id_materia`,`fecha_asistencia`),
  KEY `registrado_por` (`registrado_por`),
  KEY `idx_asistencia_materia_fecha` (`id_materia`,`fecha_asistencia`),
  KEY `idx_asistencia_estado_fecha` (`estado_asistencia`,`fecha_asistencia`),
  CONSTRAINT `asistencias_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `asistencias_ibfk_2` FOREIGN KEY (`id_materia`) REFERENCES `materias` (`id_materia`) ON DELETE RESTRICT,
  CONSTRAINT `asistencias_ibfk_3` FOREIGN KEY (`registrado_por`) REFERENCES `profesores` (`id_profesor`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Asistencia diaria por materia';

-- Tabla: clubes
CREATE TABLE `clubes` (
  `id_club` int NOT NULL AUTO_INCREMENT,
  `nombre_club` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `id_profesor_supervisor` int DEFAULT NULL COMMENT 'Profesor encargado del club',
  `capacidad_maxima` int NOT NULL DEFAULT '30',
  `horario_reunion` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ej: Martes 3-5 PM',
  `esta_activo` tinyint(1) NOT NULL DEFAULT '1',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_club`),
  UNIQUE KEY `nombre_club` (`nombre_club`),
  KEY `id_profesor_supervisor` (`id_profesor_supervisor`),
  KEY `idx_club_activo` (`esta_activo`),
  CONSTRAINT `clubes_ibfk_1` FOREIGN KEY (`id_profesor_supervisor`) REFERENCES `profesores` (`id_profesor`) ON DELETE SET NULL,
  CONSTRAINT `clubes_chk_1` CHECK ((`capacidad_maxima` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Catálogo de clubes extracurriculares (el cupo se valida en la aplicación)';

-- Tabla: membresias_club
CREATE TABLE `membresias_club` (
  `id_membresia` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_club` int NOT NULL,
  `fecha_ingreso` date NOT NULL,
  `estado_membresia` enum('Activa','Retirada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activa',
  `fecha_retiro` date DEFAULT NULL,
  `motivo_retiro` text COLLATE utf8mb4_unicode_ci,
  `activa_unica` tinyint GENERATED ALWAYS AS (if((`estado_membresia` = _utf8mb4'Activa'),1,NULL)) VIRTUAL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_membresia`),
  UNIQUE KEY `uq_una_membresia_activa` (`id_estudiante`,`id_club`,`activa_unica`),
  KEY `idx_membresia_club_estado` (`id_club`,`estado_membresia`),
  CONSTRAINT `membresias_club_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE CASCADE,
  CONSTRAINT `membresias_club_ibfk_2` FOREIGN KEY (`id_club`) REFERENCES `clubes` (`id_club`) ON DELETE CASCADE,
  CONSTRAINT `membresias_club_chk_1` CHECK ((((`estado_membresia` = _utf8mb4'Activa') and (`fecha_retiro` is null)) or ((`estado_membresia` = _utf8mb4'Retirada') and (`fecha_retiro` is not null) and (`fecha_retiro` >= `fecha_ingreso`))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Membresías de estudiantes en clubes';

-- Tabla: eventos
CREATE TABLE `eventos` (
  `id_evento` int NOT NULL AUTO_INCREMENT,
  `nombre_evento` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `tipo_evento` enum('Académico','Cultural','Deportivo','Social','Científico') COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_evento` date NOT NULL,
  `lugar` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tiene_competencia` tinyint(1) NOT NULL DEFAULT '0',
  `id_organizador` int DEFAULT NULL COMMENT 'Profesor organizador',
  `esta_activo` tinyint(1) NOT NULL DEFAULT '1',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_evento`),
  KEY `id_organizador` (`id_organizador`),
  KEY `idx_evento_fecha` (`fecha_evento`),
  KEY `idx_evento_tipo` (`tipo_evento`),
  CONSTRAINT `eventos_ibfk_1` FOREIGN KEY (`id_organizador`) REFERENCES `profesores` (`id_profesor`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Catálogo de eventos del colegio';

-- Tabla: participantes_evento
CREATE TABLE `participantes_evento` (
  `id_participacion` int NOT NULL AUTO_INCREMENT,
  `id_evento` int NOT NULL,
  `id_estudiante` int NOT NULL,
  `rol_participacion` enum('Participante','Competidor','Organizador','Asistente') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Participante',
  `posicion_obtenida` enum('1er Lugar','2do Lugar','3er Lugar','Participante') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Solo si el evento tiene competencia',
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_participacion`),
  UNIQUE KEY `uq_participacion` (`id_evento`,`id_estudiante`),
  KEY `idx_participacion_estudiante` (`id_estudiante`),
  CONSTRAINT `participantes_evento_ibfk_1` FOREIGN KEY (`id_evento`) REFERENCES `eventos` (`id_evento`) ON DELETE CASCADE,
  CONSTRAINT `participantes_evento_ibfk_2` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Participación de estudiantes en eventos';

-- Tabla: conceptos_pago
CREATE TABLE `conceptos_pago` (
  `id_concepto` int NOT NULL AUTO_INCREMENT,
  `codigo_concepto` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_concepto` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `monto_base` decimal(10,2) NOT NULL COMMENT 'Valor base (sin IVA) en pesos colombianos',
  `porcentaje_iva` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT 'Servicios educativos: 0 (excluidos)',
  `es_recurrente` tinyint(1) NOT NULL DEFAULT '0',
  `esta_activo` tinyint(1) NOT NULL DEFAULT '1',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_concepto`),
  UNIQUE KEY `codigo_concepto` (`codigo_concepto`),
  KEY `idx_concepto_activo` (`esta_activo`),
  CONSTRAINT `conceptos_pago_chk_1` CHECK ((`monto_base` >= 0)),
  CONSTRAINT `conceptos_pago_chk_2` CHECK (((`porcentaje_iva` >= 0) and (`porcentaje_iva` <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Catálogo de conceptos de pago';

-- Tabla: precios_estudiante
CREATE TABLE `precios_estudiante` (
  `id_precio` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_concepto` int NOT NULL,
  `monto_personalizado` decimal(10,2) NOT NULL COMMENT 'Valor (sin IVA) que reemplaza al monto base',
  `motivo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Beca, descuento por hermanos, etc.',
  `vigente_desde` date NOT NULL,
  `vigente_hasta` date DEFAULT NULL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_precio`),
  UNIQUE KEY `uq_precio_vigencia` (`id_estudiante`,`id_concepto`,`vigente_desde`),
  KEY `id_concepto` (`id_concepto`),
  CONSTRAINT `precios_estudiante_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `precios_estudiante_ibfk_2` FOREIGN KEY (`id_concepto`) REFERENCES `conceptos_pago` (`id_concepto`) ON DELETE RESTRICT,
  CONSTRAINT `precios_estudiante_chk_1` CHECK ((`monto_personalizado` >= 0)),
  CONSTRAINT `precios_estudiante_chk_2` CHECK (((`vigente_hasta` is null) or (`vigente_hasta` >= `vigente_desde`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Valores diferenciados por estudiante (becas, descuentos)';

-- Tabla: pagos
CREATE TABLE `pagos` (
  `id_pago` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_acudiente` int NOT NULL COMMENT 'Acudiente que realizó el pago',
  `id_concepto` int NOT NULL,
  `monto_pagado` decimal(10,2) NOT NULL COMMENT 'Valor total pagado (incluye IVA si aplica)',
  `fecha_pago` date NOT NULL,
  `metodo_pago` enum('Efectivo','Transferencia','Tarjeta Débito','Tarjeta Crédito','Cheque') COLLATE utf8mb4_unicode_ci NOT NULL,
  `numero_recibo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `anio_academico` int NOT NULL,
  `periodo_academico` enum('I','II','III','IV','Anual') COLLATE utf8mb4_unicode_ci NOT NULL,
  `notas` text COLLATE utf8mb4_unicode_ci,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_pago`),
  UNIQUE KEY `numero_recibo` (`numero_recibo`),
  KEY `idx_pago_estudiante_fecha` (`id_estudiante`,`fecha_pago`),
  KEY `idx_pago_acudiente` (`id_acudiente`),
  KEY `idx_pago_concepto` (`id_concepto`),
  KEY `idx_pago_fecha` (`fecha_pago`),
  CONSTRAINT `pagos_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `pagos_ibfk_2` FOREIGN KEY (`id_acudiente`) REFERENCES `acudientes` (`id_acudiente`) ON DELETE RESTRICT,
  CONSTRAINT `pagos_ibfk_3` FOREIGN KEY (`id_concepto`) REFERENCES `conceptos_pago` (`id_concepto`) ON DELETE RESTRICT,
  CONSTRAINT `pagos_chk_1` CHECK ((`monto_pagado` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Pagos realizados';

-- Tabla: cargos_estudiante
CREATE TABLE `cargos_estudiante` (
  `id_cargo` int NOT NULL AUTO_INCREMENT,
  `id_estudiante` int NOT NULL,
  `id_concepto` int NOT NULL,
  `monto_cargo` decimal(10,2) NOT NULL COMMENT 'Valor causado (sin IVA), ya con descuentos/becas',
  `anio_academico` int NOT NULL,
  `periodo_academico` enum('I','II','III','IV','Anual') COLLATE utf8mb4_unicode_ci NOT NULL,
  `mes_cargo` tinyint NOT NULL COMMENT 'Mes (1-12) de causación; evita duplicar la pensión de un mes',
  `fecha_vencimiento` date NOT NULL,
  `estado` enum('Pendiente','Pagado','Anulado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pendiente',
  `id_pago` int DEFAULT NULL COMMENT 'Pago que saldó el cargo',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_cargo`),
  UNIQUE KEY `uq_cargo` (`id_estudiante`,`id_concepto`,`anio_academico`,`mes_cargo`),
  UNIQUE KEY `id_pago` (`id_pago`),
  KEY `id_concepto` (`id_concepto`),
  KEY `idx_cargo_mora` (`estado`,`fecha_vencimiento`),
  CONSTRAINT `cargos_estudiante_ibfk_1` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `cargos_estudiante_ibfk_2` FOREIGN KEY (`id_concepto`) REFERENCES `conceptos_pago` (`id_concepto`) ON DELETE RESTRICT,
  CONSTRAINT `cargos_estudiante_ibfk_3` FOREIGN KEY (`id_pago`) REFERENCES `pagos` (`id_pago`) ON DELETE RESTRICT,
  CONSTRAINT `cargos_estudiante_chk_1` CHECK ((`monto_cargo` >= 0)),
  CONSTRAINT `cargos_estudiante_chk_2` CHECK ((`mes_cargo` between 1 and 12)),
  CONSTRAINT `cargos_estudiante_chk_3` CHECK ((((`estado` = _utf8mb4'Pagado') and (`id_pago` is not null)) or ((`estado` <> _utf8mb4'Pagado') and (`id_pago` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Obligaciones de pago; morosos = Pendiente con vencimiento > 1 mes';

-- Tabla: facturas
CREATE TABLE `facturas` (
  `id_factura` int NOT NULL AUTO_INCREMENT,
  `numero_factura` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Consecutivo (ej: LH-000123)',
  `id_acudiente` int NOT NULL COMMENT 'Cliente facturado',
  `fecha_emision` date NOT NULL,
  `subtotal` decimal(12,2) NOT NULL,
  `valor_iva` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total` decimal(12,2) NOT NULL,
  `cufe` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CUFE simulado (hash)',
  `resolucion_dian` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Resolución de habilitación (simulada)',
  `contenido_qr` text COLLATE utf8mb4_unicode_ci COMMENT 'Texto codificado en el QR simulado',
  `nombre_archivo_pdf` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ruta_archivo` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_factura`),
  UNIQUE KEY `numero_factura` (`numero_factura`),
  UNIQUE KEY `cufe` (`cufe`),
  KEY `idx_factura_fecha` (`fecha_emision`),
  KEY `idx_factura_acudiente` (`id_acudiente`),
  CONSTRAINT `facturas_ibfk_1` FOREIGN KEY (`id_acudiente`) REFERENCES `acudientes` (`id_acudiente`) ON DELETE RESTRICT,
  CONSTRAINT `facturas_chk_1` CHECK (((`subtotal` >= 0) and (`valor_iva` >= 0))),
  CONSTRAINT `facturas_chk_2` CHECK ((`total` = (`subtotal` + `valor_iva`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Facturas electrónicas generadas';

-- Tabla: detalle_factura
CREATE TABLE `detalle_factura` (
  `id_detalle` int NOT NULL AUTO_INCREMENT,
  `id_factura` int NOT NULL,
  `id_pago` int NOT NULL COMMENT 'Un pago se factura una sola vez',
  `descripcion` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cantidad` int NOT NULL DEFAULT '1',
  `valor_unitario` decimal(10,2) NOT NULL,
  `subtotal` decimal(12,2) NOT NULL,
  `porcentaje_iva` decimal(5,2) NOT NULL DEFAULT '0.00',
  `valor_iva` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total` decimal(12,2) NOT NULL,
  PRIMARY KEY (`id_detalle`),
  UNIQUE KEY `id_pago` (`id_pago`),
  KEY `idx_detalle_factura` (`id_factura`),
  CONSTRAINT `detalle_factura_ibfk_1` FOREIGN KEY (`id_factura`) REFERENCES `facturas` (`id_factura`) ON DELETE RESTRICT,
  CONSTRAINT `detalle_factura_ibfk_2` FOREIGN KEY (`id_pago`) REFERENCES `pagos` (`id_pago`) ON DELETE RESTRICT,
  CONSTRAINT `detalle_factura_chk_1` CHECK ((`cantidad` > 0)),
  CONSTRAINT `detalle_factura_chk_2` CHECK ((`subtotal` = (`cantidad` * `valor_unitario`))),
  CONSTRAINT `detalle_factura_chk_3` CHECK ((`total` = (`subtotal` + `valor_iva`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Líneas de cada factura';

-- Tabla: categorias_recurso
CREATE TABLE `categorias_recurso` (
  `id_categoria` int NOT NULL AUTO_INCREMENT,
  `nombre_categoria` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_categoria`),
  UNIQUE KEY `nombre_categoria` (`nombre_categoria`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Categorías de recursos';

-- Tabla: recursos
CREATE TABLE `recursos` (
  `id_recurso` int NOT NULL AUTO_INCREMENT,
  `codigo_recurso` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Código de inventario único',
  `nombre_recurso` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_categoria` int NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `fecha_adquisicion` date DEFAULT NULL,
  `ubicacion_fisica` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado_recurso` enum('Disponible','Prestado','En Mantenimiento','Dado de Baja') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Disponible',
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_recurso`),
  UNIQUE KEY `codigo_recurso` (`codigo_recurso`),
  KEY `idx_recurso_estado` (`estado_recurso`),
  KEY `idx_recurso_categoria` (`id_categoria`),
  KEY `idx_recurso_nombre` (`nombre_recurso`),
  CONSTRAINT `recursos_ibfk_1` FOREIGN KEY (`id_categoria`) REFERENCES `categorias_recurso` (`id_categoria`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Inventario de recursos prestables';

-- Tabla: prestamos_estudiante
CREATE TABLE `prestamos_estudiante` (
  `id_prestamo` int NOT NULL AUTO_INCREMENT,
  `id_recurso` int NOT NULL,
  `id_estudiante` int NOT NULL,
  `fecha_prestamo` date NOT NULL,
  `fecha_devolucion_esperada` date NOT NULL,
  `fecha_devolucion_real` date DEFAULT NULL,
  `estado_prestamo` enum('Activo','Devuelto','Vencido') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activo',
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `prestamo_abierto` tinyint GENERATED ALWAYS AS (if((`estado_prestamo` in (_utf8mb4'Activo',_utf8mb4'Vencido')),1,NULL)) VIRTUAL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_prestamo`),
  UNIQUE KEY `uq_un_prestamo_abierto` (`id_recurso`,`prestamo_abierto`),
  KEY `idx_prestamo_est_estudiante` (`id_estudiante`),
  KEY `idx_prestamo_est_vencimiento` (`estado_prestamo`,`fecha_devolucion_esperada`),
  CONSTRAINT `prestamos_estudiante_ibfk_1` FOREIGN KEY (`id_recurso`) REFERENCES `recursos` (`id_recurso`) ON DELETE RESTRICT,
  CONSTRAINT `prestamos_estudiante_ibfk_2` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`) ON DELETE RESTRICT,
  CONSTRAINT `prestamos_estudiante_chk_1` CHECK ((`fecha_devolucion_esperada` >= `fecha_prestamo`)),
  CONSTRAINT `prestamos_estudiante_chk_2` CHECK (((`fecha_devolucion_real` is null) or (`fecha_devolucion_real` >= `fecha_prestamo`))),
  CONSTRAINT `prestamos_estudiante_chk_3` CHECK ((((`estado_prestamo` = _utf8mb4'Devuelto') and (`fecha_devolucion_real` is not null)) or ((`estado_prestamo` <> _utf8mb4'Devuelto') and (`fecha_devolucion_real` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Préstamos de recursos a estudiantes';

-- Tabla: prestamos_profesor
CREATE TABLE `prestamos_profesor` (
  `id_prestamo` int NOT NULL AUTO_INCREMENT,
  `id_recurso` int NOT NULL,
  `id_profesor` int NOT NULL,
  `fecha_prestamo` date NOT NULL,
  `fecha_devolucion_esperada` date NOT NULL,
  `fecha_devolucion_real` date DEFAULT NULL,
  `estado_prestamo` enum('Activo','Devuelto','Vencido') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activo',
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `prestamo_abierto` tinyint GENERATED ALWAYS AS (if((`estado_prestamo` in (_utf8mb4'Activo',_utf8mb4'Vencido')),1,NULL)) VIRTUAL,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_prestamo`),
  UNIQUE KEY `uq_un_prestamo_abierto` (`id_recurso`,`prestamo_abierto`),
  KEY `idx_prestamo_prof_profesor` (`id_profesor`),
  KEY `idx_prestamo_prof_vencimiento` (`estado_prestamo`,`fecha_devolucion_esperada`),
  CONSTRAINT `prestamos_profesor_ibfk_1` FOREIGN KEY (`id_recurso`) REFERENCES `recursos` (`id_recurso`) ON DELETE RESTRICT,
  CONSTRAINT `prestamos_profesor_ibfk_2` FOREIGN KEY (`id_profesor`) REFERENCES `profesores` (`id_profesor`) ON DELETE RESTRICT,
  CONSTRAINT `prestamos_profesor_chk_1` CHECK ((`fecha_devolucion_esperada` >= `fecha_prestamo`)),
  CONSTRAINT `prestamos_profesor_chk_2` CHECK (((`fecha_devolucion_real` is null) or (`fecha_devolucion_real` >= `fecha_prestamo`))),
  CONSTRAINT `prestamos_profesor_chk_3` CHECK ((((`estado_prestamo` = _utf8mb4'Devuelto') and (`fecha_devolucion_real` is not null)) or ((`estado_prestamo` <> _utf8mb4'Devuelto') and (`fecha_devolucion_real` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Préstamos de recursos a profesores';

